{
  "milestones": [
    {
      "id": "m1",
      "title": "Add key_func parameter to cache",
      "requests": [
        "R1"
      ],
      "requirement": "@cache should accept a key_func argument to determine the cache key, similar to @memoize.",
      "observable": "cache(lambda x: x*2, key_func=lambda x: x)(5) returns 10; cache(lambda x: x*2)(5) returns 10 (default behavior preserved)",
      "public_names": [
        "cache"
      ],
      "requires": [],
      "why_requires": "cache currently has a hardcoded default key function. To unify with memoize which explicitly accepts key_func, we must first expose this parameter in cache's signature and usage."
    },
    {
      "id": "m2",
      "title": "Add invalidate method to cache wrapper",
      "requests": [
        "R1"
      ],
      "requirement": "The decorated function returned by @cache should have an .invalidate(key) method that removes the specific entry from the cache.",
      "observable": "f = cache(60)(func); f.invalidate(some_key); assert some_key not in f.cache_dict",
      "public_names": [
        "cache"
      ],
      "requires": [
        "m1"
      ],
      "why_requires": "Adding .invalidate requires access to the internal cache dictionary and the key generation logic. m1 establishes the key_func handling, making it possible to implement .invalidate correctly using the same key function used for storage."
    },
    {
      "id": "m3",
      "title": "Unify API: Add memory/invalidate_all/skip to cache and memoize",
      "requests": [
        "R1"
      ],
      "requirement": "Both @cache and @memoize wrappers should expose .memory (or equivalent), .invalidate_all(), and support .skip behavior if applicable, ensuring consistent public API.",
      "observable": "cache_decorated.invaliate_all(); memoize_decorated.invaliate_all(); cache_decorated.memory is accessible or aliased appropriately",
      "public_names": [
        "cache",
        "memoize"
      ],
      "requires": [
        "m2"
      ],
      "why_requires": "This milestone finalizes the unification requested in R1. It builds on m2 (which added .invalidate to cache) by adding .invalidate_all and standardizing the 'memory' attribute name/access across both decorators. It also ensures memoize aligns with cache's timeout-aware structure where relevant, or vice versa, creating a truly unified interface."
    }
  ],
  "expected_causes": [
    "Implementer might fail to update the key generation logic in cache when adding key_func, leading to inconsistent keys between storage and invalidation.",
    "Implementer might confuse .memory attribute naming between memoize (dict) and cache (dict of tuples), causing AttributeError or incorrect behavior.",
    "Implementer might forget to add .invalidate_all to cache, only adding .invalidate, thus failing the 'unify' requirement."
  ],
  "verifier_plan": "Test m1: Verify cache accepts key_func and uses it. Test m2: Verify cache wrapper has .invalidate(key) and correctly removes the specified key. Test m3: Verify both cache and memoize wrappers have .invalidate_all() and a consistent way to access/clear all cached data (e.g., .memory or direct clear). Check that existing functionality (timeout for cache, skip for memoize) still works."
}
